import { BrantaServerBaseUrls } from '../enums/brantaServerBaseUrl.js';
import { DestinationType } from '../enums/destinationType.js';
import { PrivacyMode } from '../enums/privacyMode.js';
const subtle = () => {
    const c = globalThis.crypto;
    if (!c?.subtle) {
        throw new Error('Web Crypto API is not available. See README for React Native polyfill instructions.');
    }
    return c.subtle;
};
export function getUrl(server) {
    const url = BrantaServerBaseUrls[server];
    if (!url)
        throw new Error(`No URL defined for ${server}`);
    return url;
}
export function getUri(defaultOptions, overrideOptions) {
    return new URL(getBaseUrl(defaultOptions, overrideOptions));
}
export function getBaseUrl(defaultOptions, overrideOptions) {
    const baseUrl = overrideOptions?.baseUrl ?? defaultOptions?.baseUrl;
    if (!baseUrl)
        throw new Error('Branta: BaseUrl is a required option.');
    return getUrl(baseUrl);
}
export function getPrivacy(defaultOptions, overrideOptions, fallback = PrivacyMode.Strict) {
    return overrideOptions?.privacy ?? defaultOptions?.privacy ?? fallback;
}
export function getApiKey(defaultOptions, overrideOptions) {
    return overrideOptions?.defaultApiKey ?? defaultOptions?.defaultApiKey;
}
export function getHmacSecret(defaultOptions, overrideOptions) {
    return overrideOptions?.hmacSecret ?? defaultOptions?.hmacSecret;
}
export function isBolt11(value) {
    const lower = value.toLowerCase();
    return lower.startsWith('lnbc') || lower.startsWith('lntb') || lower.startsWith('lnbcrt');
}
export function isArk(value) {
    return value.toLowerCase().startsWith('ark1');
}
export function getHashZkType(value) {
    if (isBolt11(value))
        return DestinationType.Bolt11;
    if (isArk(value))
        return DestinationType.ArkAddress;
    return undefined;
}
export async function toNormalizedHash(value) {
    const normalized = value.toLowerCase();
    const bytes = new TextEncoder().encode(normalized);
    const hash = new Uint8Array(await subtle().digest('SHA-256', bytes));
    let hex = '';
    for (let i = 0; i < hash.length; i++) {
        hex += hash[i].toString(16).padStart(2, '0').toUpperCase();
    }
    return hex;
}
export function toUrlFragment(keys) {
    const entries = Object.entries(keys);
    if (entries.length === 0)
        return '';
    const fragments = entries.map(([k, v]) => `k-${k}=${v}`);
    return '#' + fragments.join('&');
}
